    '.m42-feu{width:120px;height:120px;margin:6px auto;border-radius:50% 50% 45% 45%;background:radial-gradient(circle at 50% 75%,#fff6a0 0,#ffb030 25%,#e2481c 55%,rgba(120,20,0,0) 72%);animation:m42feu .35s infinite alternate;filter:blur(1px)}',
    '@keyframes m42feu{from{transform:scale(1,1)}to{transform:scale(1.06,.94) translateY(3px)}}',
    '.m42-fx{position:absolute;pointer-events:none;transform:translate(-50%,-50%);z-index:3}',
    '.m42-fx-rune{border-radius:50%;border:3px dashed var(--c);box-shadow:0 0 18px var(--c),inset 0 0 18px var(--c);animation:m42tourne 9s linear infinite;display:flex;align-items:center;justify-content:center;color:var(--c);font-size:40px;text-shadow:0 0 12px var(--c)}',
    '.m42-fx-portail{border-radius:50%;background:conic-gradient(from 0deg,var(--c),transparent,var(--c),transparent,var(--c));filter:blur(3px);animation:m42tourne 2.2s linear infinite;box-shadow:0 0 40px var(--c)}',
    '.m42-fx-aura{border-radius:50%;background:radial-gradient(circle,var(--c) 0,transparent 70%);animation:m42pulse 2.4s ease-in-out infinite}',
