    const fl = 'float:left;font-size:3.2em;line-height:.85;padding:4px 8px 0 0;margin-top:2px;color:' + c + ';font-family:Palatino,Georgia,serif;font-weight:700;text-shadow:1px 1px 0 rgba(0,0,0,.18)';
    r.push('.av41-boite > p:first-of-type::first-letter{' + fl + '}');
    r.push('#modal-text::first-letter{' + fl + '}');
    r.push('.av41-boite h2::after{content:" \u2766";opacity:.55;font-size:.75em}');
