    const box = PlayerUI.mk("div", { background: "#161A25", color: "#E9E6DD", border: "1px solid #242938", borderRadius: "12px", padding: "18px", width: "min(92%,420px)", maxHeight: "86%", overflowY: "auto", fontFamily: "system-ui,sans-serif", fontSize: (15 * scale) + "px", boxSizing: "border-box" });
