    const t = PlayerUI.mk("div", { position: "absolute", left: "50%", bottom: "calc(env(safe-area-inset-bottom,0px) + 28px)", transform: "translateX(-50%)", background: "rgba(22,26,37,.92)", color: "#E9E6DD", border: "1px solid #242938", borderRadius: "999px", padding: "8px 16px", fontFamily: "system-ui,sans-serif", fontSize: "14px", zIndex: "3000", pointerEvents: "none", transition: "opacity .3s", opacity: "1", whiteSpace: "nowrap" });
