      const lp = hmk("div", { width: "100%", height: "100%" });
      outer.appendChild(fx); fx.appendChild(lp);
      const T = { L: L, outer: outer, fx: fx, loopEl: lp, index: i + 1, px: 0, py: 0, rot: 0, built: false };
      layers[L.id] = T;
      root.appendChild(outer);
