        const b = hmk("button", { position: "relative", width: "100%", minHeight: "44px", border: "none", padding: L.images.normal ? "0" : "0.5em 1em", margin: "0", cursor: "pointer", color: L.color, fontFamily: '"' + L.fontFamily + '", Georgia, serif', background: L.images.normal ? "transparent" : L.boxColor, borderRadius: L.images.normal ? "0" : "0.4em", display: "flex", alignItems: "center", justifyContent: "center", transition: "transform .12s ease, opacity .12s ease", textShadow: L.shadow ? "0 2px 8px rgba(0,0,0,.7)" : "none", webkitTapHighlightColor: "transparent" });
        b.type = "button"; b.setAttribute("data-action", L.action);
        if (L.strokeWidth > 0) b.style.webkitTextStroke = L.strokeWidth + "px " + L.strokeColor;
        if (L.images.normal) { const im = hmk("img", { width: "100%", display: "block", pointerEvents: "none" }); im.setAttribute("alt", ""); im.setAttribute("draggable", "false"); b.appendChild(im); T.img = im; }
        const lab = hmk("span", { position: L.images.normal ? "absolute" : "static", pointerEvents: "none", textAlign: "center", lineHeight: "1.1" });
        b.appendChild(lab); T.label = lab; T.btn = b;
