  const eff = runActions(r.actions);
  const textes = eff.filter(function(e){ return e.kind === 'text'; }).map(function(e){ return e.text; });
  const nav = pickNavigate(eff, null);
  const dlg = eff.filter(function(e){ return e.kind === 'dialogue'; })[0];
